const body = $input.all()[0].json.body || {};
const events = body.events || [];

if (events.length === 0) {
  throw new Error('No LINE events');
}

const event = events[0];

if (event.type !== 'message' || event.message.type !== 'text') {
  return [{ json: { skip: true, reason: 'Non-text message: ' + (event.message?.type || 'unknown') } }];
}

return [{
  json: {
    userMessage: event.message.text,
    replyToken: event.replyToken,
    userId: event.source?.userId,
    groupId: event.source?.groupId || null,
    messageId: event.message.id
  }
}];

const compilerRes = $input.all()[0].json;
const payload = compilerRes.compiled_payload || {};
const replyToken = $('📝 Parse LINE Event').first().json.replyToken;

const textSpoken = payload.text || 'รับทราบคำสั่งเรียบร้อยแล้วค่ะ';
const face = payload.face || 'HAPPY';
const status = payload.emergency ? '🛑 EMERGENCY STOP' : '✅ Working';

const details = [];
if (payload.motion) details.push('🚶 เดิน: x=' + payload.motion.x + 'm');
if (payload.head) details.push('🔄 หัว: yaw=' + payload.head.yaw + '° pitch=' + payload.head.pitch + '°');
if (payload.wheel_lights) details.push('💡 ไฟ: ' + payload.wheel_lights.mode);
if (payload.action) details.push('🎬 Action #' + payload.action.action_id);

const reply = {
  type: 'flex',
  altText: '🤖 ' + textSpoken.substring(0, 60),
  contents: {
    type: 'bubble',
    size: 'kilo',
    header: {
      type: 'box',
      layout: 'vertical',
      backgroundColor: payload.emergency ? '#DC2626' : '#2563EB',
      contents: [{
        type: 'text',
        text: '🤖 Zenbo | IntelSphere AI',
        weight: 'bold',
        color: '#FFFFFF',
        size: 'md'
      }]
    },
    body: {
      type: 'box',
      layout: 'vertical',
      spacing: 'md',
      contents: [
        {
          type: 'text',
          text: '💬 "' + compilerRes.original_command + '"',
          size: 'xs',
          color: '#64748B',
          wrap: true
        },
        { type: 'separator', margin: 'sm' },
        {
          type: 'text',
          text: '🗣️ ' + textSpoken,
          size: 'sm',
          weight: 'bold',
          color: '#1E293B',
          wrap: true
        },
        {
          type: 'box',
          layout: 'horizontal',
          spacing: 'sm',
          margin: 'md',
          contents: [
            { type: 'text', text: '😊 ' + face, size: 'xs', color: '#475569', flex: 1 },
            { type: 'text', text: status, size: 'xs', color: payload.emergency ? '#DC2626' : '#10B981', flex: 1, align: 'end' }
          ]
        }
      ].concat(details.map(function(d) {
        return { type: 'text', text: d, size: 'xs', color: '#6366F1', margin: 'sm' };
      }))
    }
  }
};

return [{ json: { replyToken: replyToken, replyPayload: reply } }];
